int _lifecycle_wait_for_work(void) {
    LOCK(&g_lifecycle.lock);
    if (g_lifecycle.pending_jobs == 0) {
        pthread_cond_wait(&g_lifecycle.cond, &g_lifecycle.lock);
    }

    g_lifecycle.pending_jobs--;
    UNLOCK(&g_lifecycle.lock);
    return 0;
}

